 14	/* Effective funnel rank for any candidate stage. Terminal/negative stages map
 15	   to the furthest pipeline point they actually reached. */
 16	export const STAGE_RANK: Record<string, number> = {
 17	  Sourced: 0,
 18	  Contacted: 1,
 19	  Replied: 2,
 20	  Interested: 3,
 21	  Booked: 4,
 22	  Interviewed: 5,
 23	  Offer: 6,
 24	  Hired: 7,
 25	  "Not Interested": 2,
 26	  Rejected: 1,
 27	  Suppressed: 1,
 28	};
 29	
 30	export function stageRank(stage: string): number {
 31	  return STAGE_RANK[stage] ?? 0;
 32	}
 33	
 34	/* The furthest funnel point a candidate ever reached, even if their current
 35	   `stage` later regressed to a terminal/negative one (Rejected, Suppressed).
 36	   Takes the max of the tracked high-water mark and the live stage rank so a
 37	   stale/missing maxStageRank can never under-report the current stage. */
 38	export function effectiveStageRank(c: Candidate): number {
 39	  return Math.max(c.maxStageRank ?? 0, stageRank(c.stage));
 40	}
 41	
 42	/* Computes the {stage, maxStageRank} pair for a candidate transitioning to a
 43	   new stage. Every store.ts mutation site that sets `candidate.stage`
 44	   (setCandidateStage, booking creation/completion, suppression, reply
 45	   handling, ...) must merge this in, or a later regression to a terminal
 46	   stage (Suppressed/Rejected) silently erases an earlier high-water mark
 47	   (e.g. Interviewed) and effectiveStageRank() under-reports it. */
 48	export function withStage(
 49	  prev: Pick<Candidate, "stage" | "maxStageRank">,
 50	  stage: CandidateStage,
 51	): { stage: CandidateStage; maxStageRank: number } {
 52	  return {
 53	    stage,
 54	    maxStageRank: Math.max(prev.maxStageRank ?? 0, stageRank(prev.stage), stageRank(stage)),
 55	  };
 56	}
 57	
 58	/* Elapsed hours from `createdAt` to the earliest `startTime` among the given
 59	   bookings — each booking's *scheduled* interview time, not the moment the
 60	   booking record itself was created. This is the single, canonical
 61	   time-to-first-interview computation shared by store.ts (live campaigns)
 62	   and seed.ts (seeded demo campaigns) so both report the same KPI meaning.
 63	   Returns null when there are no bookings yet. */
 64	export function firstInterviewElapsedHours(
 65	  bookings: Pick<Booking, "startTime">[],
 66	  createdAt: string,
 67	): number | null {
 68	  const firstStartTime = bookings.reduce<string | null>(
 69	    (min, b) => (min === null || b.startTime < min ? b.startTime : min),
 70	    null,
 71	  );
 72	  if (firstStartTime === null) return null;
 73	  return Math.max(
 74	    0,
 75	    Math.round((new Date(firstStartTime).getTime() - new Date(createdAt).getTime()) / 3_600_000),
 76	  );
 77	}
 78	
 79	const FUNNEL_RANK: Record<string, number> = {
 80	  Sourced: 0,
 81	  Contacted: 1,
 82	  Replied: 2,
 83	  Interested: 3,
 84	  Booked: 4,
 85	  Interviewed: 5,
 86	  Hired: 7,
 87	};
 88	
 89	export function funnelForCandidates(candidates: Candidate[]): FunnelPoint[] {
 90	  return FUNNEL_STAGES.map((stage) => ({
 91	    stage,
 92	    count: candidates.filter((c) => effectiveStageRank(c) >= FUNNEL_RANK[stage]).length,
 93	  }));
 94	}
