118	export function isRealSendFact(
119	  message: Pick<OutreachMessage, "dryRun" | "sentAt">,
120	): boolean {
121	  return message.dryRun === false && message.sentAt != null;
122	}
123	
124	function candidatesInScope(
125	  candidates: Candidate[],
126	  { live, campaignId }: RealFunnelOptions,
127	): Candidate[] {
128	  return candidates.filter(
129	    (candidate) =>
130	      (campaignId == null || candidate.campaignId === campaignId) &&
131	      (!live || candidate.provenance !== "synthetic"),
132	  );
133	}
134	
135	function replyIsPositive(reply: Pick<ClassifiedReply, "intent">): boolean {
136	  return reply.intent === "INTERESTED" || reply.intent === "QUALIFIED_INTEREST";
137	}
138	
139	/* Canonical real-send funnel facts.
140	   Pipeline-stage high-water counts remain available via effectiveStageRank() and
141	   funnelForCandidates(); this derivation is for executive/contact KPIs that
142	   must only count completed real sends, replies, and bookings. */
143	export function realFunnelFacts(
144	  state: RealFunnelState,
145	  options: RealFunnelOptions,
146	): RealFunnelFacts {
147	  const eligibleCandidates = candidatesInScope(state.candidates, options);
148	  const eligibleCandidateIds = new Set(eligibleCandidates.map((candidate) => candidate.id));
149	  const inCampaign = (campaignId: string) =>
150	    options.campaignId == null || campaignId === options.campaignId;
151	
152	  const contactedCandidateIds = new Set(
153	    state.outreach
154	      .filter(
155	        (message) =>
156	          inCampaign(message.campaignId) &&
157	          eligibleCandidateIds.has(message.candidateId) &&
158	          isRealSendFact(message),
159	      )
160	      .map((message) => message.candidateId),
161	  );
162	
163	  const replies = state.replies.filter(
164	    (reply) =>
165	      inCampaign(reply.campaignId) &&
166	      contactedCandidateIds.has(reply.candidateId),
167	  );
168	  const repliedCandidateIds = new Set(replies.map((reply) => reply.candidateId));
169	  const positiveReplyCandidateIds = new Set(
170	    replies.filter(replyIsPositive).map((reply) => reply.candidateId),
171	  );
172	  const bookings = state.bookings.filter(
173	    (booking) =>
174	      inCampaign(booking.campaignId) &&
175	      contactedCandidateIds.has(booking.candidateId),
176	  );
177	
178	  const contacted = contactedCandidateIds.size;
179	  const repliedCount = repliedCandidateIds.size;
180	  const positiveReplies = positiveReplyCandidateIds.size;
181	
182	  return {
183	    sourced: eligibleCandidates.length,
184	    contacted,
185	    repliedCount,
186	    positiveReplies,
187	    booked: bookings.length,
188	    replyRate: contacted ? repliedCount / contacted : 0,
189	    positiveReplyRate: contacted ? positiveReplies / contacted : 0,
190	    candidateIds: [...eligibleCandidateIds],
191	    contactedCandidateIds: [...contactedCandidateIds],
192	  };
193	}
