203	export function missionControlHudValues(
204	  state: RealFunnelState,
205	  options: RealFunnelOptions,
206	): MissionControlHudValues {
207	  const facts = realFunnelFacts(state, options);
208	  const eligibleCandidateIds = new Set(facts.candidateIds);
209	  const scopedOutreach = state.outreach.filter(
210	    (message) =>
211	      eligibleCandidateIds.has(message.candidateId) &&
212	      (options.campaignId == null || message.campaignId === options.campaignId),
213	  );
214	
215	  return {
216	    sourced: facts.sourced,
217	    contacted: facts.contacted,
218	    drafted: scopedOutreach.length,
219	    approved: scopedOutreach.filter((message) => message.approvedBy != null).length,
220	    booked: facts.booked,
221	  };
222	}
