153	  for (const c of converters) {
154	    for (const b of c.matchBreakdown) {
155	      const cur = dimSum.get(b.key) ?? { sum: 0, n: 0 };
156	      cur.sum += b.score;
157	      cur.n += 1;
158	      dimSum.set(b.key, cur);
159	    }
160	  }
161	  let topDimension: OutcomeAnalysis["topDimension"] = null;
162	  for (const [key, v] of dimSum) {
163	    const avg = v.n ? v.sum / v.n : 0;
164	    if (!topDimension || avg > topDimension.avg) topDimension = { key, avg: round(avg) };
165	  }
166	
167	  const totalReplies = state.replies.length || 1;
168	  const unclearRate = state.replies.filter((r) => r.intent === "UNCLEAR").length / totalReplies;
