170	  return {
171	    toneRates,
172	    bestTone,
173	    topDimension,
174	    unclearRate,
175	    converted: converters.length,
176	    contacted: state.candidates.filter((c) => stageRank(c.stage) >= 1).length,
177	  };
178	}
