180	/* ---- Proposals (concrete, data-backed) ----------------------------------- */
181	
182	export function proposeSkillUpdates(state: HermesState): SkillUpdate[] {
183	  const a = analyzeOutcomes(state);
184	  const now = new Date().toISOString();
185	  const out: SkillUpdate[] = [];
186	
187	  if (a.bestTone) {
188	    const cur = getSkill(state.skills, "outreach_skill")?.params.preferredTone ?? "Casual Professional";
189	    if (a.bestTone !== cur) {
190	      const r = a.toneRates.find((t) => t.tone === a.bestTone)!;
191	      out.push(mk("outreach_skill", `Default to a ${a.bestTone.toLowerCase()} tone`,
192	        `${a.bestTone} converted ${(r.rate * 100).toFixed(0)}% of ${r.sent} sends, the best of the tested tones.`,
193	        `Default tone: ${cur}.`, `Default tone: ${a.bestTone}.`, "+ projected reply lift", now));
194	    }
195	  }
196	  if (a.topDimension && a.topDimension.key !== "skills") {
197	    out.push(mk("scoring_skill", `Increase the weight of "${a.topDimension.key}"`,
198	      `Converters average ${a.topDimension.avg} on ${a.topDimension.key}, under-weighted today.`,
199	      `Standard weights.`, `Nudge ${a.topDimension.key} up by ~6 points.`, "Better recall on real converters", now));
200	  } else {
201	    out.push(mk("scoring_skill", "Hold scoring weights",
202	      "Skills remains the strongest predictor of conversion: keep it dominant.",
203	      "Skills weight 34%.", "Skills weight 34% (held).", "Stable precision", now));
204	  }
205	  if (a.unclearRate > 0.15) {
206	    out.push(mk("reply_classification_skill", "Lower the qualified-interest floor",
207	      `${(a.unclearRate * 100).toFixed(0)}% of replies landed UNCLEAR: too many hot leads to manual review.`,
208	      "Qualified-interest floor 0.70.", "Qualified-interest floor 0.66.", "Fewer hot leads lost", now));
209	  }
210	  out.push(mk("sourcing_skill", "Lead queries with the top required skill",
211	    "First-skill-led queries surfaced the highest-scoring candidates this cycle.",
212	    "Balanced multi-skill queries.", "Top-skill-led queries first.", "Higher top-of-funnel quality", now));
213	
214	  return out;
215	}
