217	function mk(skill: SkillKey, title: string, rationale: string, before: string, after: string, impact: string, at: string): SkillUpdate {
218	  return { id: genId("skill"), skill, title, rationale, before, after, impact, status: "proposed", createdAt: at };
219	}
