221	/* ---- Applying a learning (the feedback into behavior) --------------------- */
222	
223	/** Compute the empirically-best params for a skill from current outcomes. */
224	export function learnedParamsFor(key: SkillKey, state: HermesState): AgentSkillParams {
225	  const a = analyzeOutcomes(state);
226	  switch (key) {
227	    case "outreach_skill":
228	      return { preferredTone: a.bestTone ?? "Casual Professional", leadWithArtifact: true };
229	    case "scoring_skill": {
230	      const cur = getSkill(state.skills, "scoring_skill")?.params.weights ?? {};
231	      if (a.topDimension && a.topDimension.key !== "skills") {
232	        return { weights: { ...cur, [a.topDimension.key]: (cur[a.topDimension.key] ?? defaultWeight(a.topDimension.key)) + 6 } };
233	      }
234	      return { weights: cur };
235	    }
236	    case "reply_classification_skill":
237	      return { qualifiedInterestFloor: a.unclearRate > 0.15 ? 0.66 : 0.7 };
238	    case "sourcing_skill":
239	      return { preferredPlatforms: getSkill(state.skills, "sourcing_skill")?.params.preferredPlatforms ?? ["GitHub", "LinkedIn"] };
240	    default:
241	      return {};
242	  }
243	}
244	
245	function defaultWeight(key: keyof ScoringWeights): number {
246	  const d: ScoringWeights = { skills: 34, experience: 22, companyStage: 12, industry: 12, location: 10, activity: 10 };
247	  return d[key];
248	}
249	
250	/** Return a new skill version with params merged + a history entry. */
251	export function applyLearning(skill: AgentSkill, patch: AgentSkillParams, summary: string): AgentSkill {
252	  const now = new Date().toISOString();
253	  const version = skill.version + 1;
254	  return {
255	    ...skill,
256	    version,
257	    params: { ...skill.params, ...patch, weights: { ...skill.params.weights, ...patch.weights } },
258	    metrics: { applied: skill.metrics.applied + 1, outcomeSignal: round(skill.metrics.outcomeSignal + 0.5, 1) },
259	    updatedAt: now,
260	    content: `${skill.content}\n\n<!-- v${version} (${now.slice(0, 10)}): ${summary} -->`,
261	    history: [{ version, summary, at: now }, ...skill.history],
262	  };
263	}
264	
265	/** Effective scoring weights = base defaults overlaid with the learned scoring skill. */
266	export function effectiveWeights(base: ScoringWeights, skills: AgentSkill[]): ScoringWeights {
267	  const learned = getSkill(skills, "scoring_skill")?.params.weights ?? {};
268	  return { ...base, ...learned };
269	}
270	
271	export function effectiveTone(skills: AgentSkill[], fallback: OutreachTone = "Casual Professional"): OutreachTone {
272	  return getSkill(skills, "outreach_skill")?.params.preferredTone ?? fallback;
273	}

