 * Canonical real-send KPI facts must not count demo sends, approvals awaiting
 * delivery, or synthetic candidates as live contact facts.
 * Run: tsx tests/metrics-canonical.mts
 */
import {
  computeCampaignMetrics,
  globalKpis,
  isRealSendFact,
  missionControlHudValues,
  realFunnelFacts,
} from "../src/lib/metrics";
import type {
  Booking,
  Campaign,
  Candidate,
  HermesState,
  OutreachLedgerEntry,
  OutreachMessage,
} from "../src/lib/types";

let pass = 0,
  fail = 0;
function ok(name: string, cond: boolean) {
  if (cond) {
    pass++;
  } else {
    fail++;
    console.log("FAIL:", name);
  }
}

const campaignId = "camp-real";
const sentAt = "2026-07-10T12:00:00.000Z";

function candidate(id: string, provenance: Candidate["provenance"] = "live"): Candidate {
  return {
    id,
    campaignId,
    name: id,
    title: "Engineer",
    company: "Example",
    location: "Paris",
    email: `${id}@example.com`,
    linkedinUrl: null,
    githubUrl: null,
    sourcePlatform: "GitHub",
    sourceQuery: "engineer",
    matchScore: 82,
    matchBreakdown: [],
    techStack: [],
    yearsExperience: 6,
    companyStageExperience: [],
    industryExperience: [],
    recentActivity: "",
    stage: "Sourced",
    lastContactedAt: null,
    outreachHistory: [],
    replyHistory: [],
    booking: null,
    complianceFlags: { needsVisaCheck: false, missingContactInfo: false, gdprSensitive: false },
    createdAt: sentAt,
    provenance,
  } as Candidate;
}

function outreach(
  id: string,
  candidateId: string,
  dryRun: boolean,
  messageSentAt: string | null,
  status: OutreachMessage["status"] = "Scheduled",
): OutreachMessage {
  return {
    id,
