function ledger(
  id: string,
  candidateId: string,
  status: OutreachLedgerEntry["status"],
): OutreachLedgerEntry {
  return {
    id,
    candidateId,
    candidateEmail: `${candidateId}@example.com`,
    seatId: "seat-1",
    campaignId,
    channel: "Email",
    status,
    reason: null,
    at: sentAt,
  };
}

function booking(id: string, candidateId: string): Booking {
  return {
    id,
    candidateId,
    campaignId,
    candidateName: candidateId,
    role: "Engineer",
    startTime: "2026-07-11T12:00:00.000Z",
